{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    required = ("nodes", "core_distance", "distances")
    for field in required:
        if field not in case:
            raise ValueError("missing required field: " + field)

    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not all(isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if not isinstance(core, dict):
        raise ValueError("core_distance must be an object")
    if set(core) != set(nodes):
        raise ValueError("core_distance must contain exactly the registered nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_number(value):
        return (
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            and value >= 0
        )

    core_out = {}
    for node in nodes:
        value = core[node]
        if not valid_number(value):
            raise ValueError("core distances must be finite non-negative numbers")
        core_out[node] = value

    node_set = set(nodes)
    seen = set()
    reachability = []
    for row in distances:
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError("each distance must be a three-item sequence")
        left, right, distance = row
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not a registered node")
        if left == right:
            raise ValueError("self-distances are not valid graph edges")
        if not valid_number(distance):
            raise ValueError("distances must be finite non-negative numbers")
        if right < left:
            left, right = right, left
        pair = (left, right)
        if pair in seen:
            raise ValueError("duplicate undirected distance")
        seen.add(pair)
        weight = max(core_out[left], core_out[right], distance)
        reachability.append([left, right, weight])

    reachability.sort(key=lambda edge: (edge[2], edge[0], edge[1]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    for edge in reachability:
        if union(edge[0], edge[1]):
            mst_edges.append(list(edge))
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    total_weight = sum(edge[2] for edge in mst_edges)
    return {
        "core_distance": core_out,
        "mutual_reachability_edges": reachability,
        "mst_edges": mst_edges,
        "total_weight": total_weight,
    }
"}
